/**
 * @method
 * @name independentreserve#fetchMarkets
 * @description retrieves data on all markets for independentreserve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Independentreserve) FetchMarketsAsync(optionalArgs ...any) <-chan AsyncResult[[]MarketInterface] {
	ch := make(chan AsyncResult[[]MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Independentreserve) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var baseCurrenciesPromise any = this.PublicGetGetValidPrimaryCurrencyCodes(params)
	//     ['Xbt', 'Eth', 'Usdt', ...]
	var quoteCurrenciesPromise any = this.PublicGetGetValidSecondaryCurrencyCodes(params)
	//     ['Aud', 'Usd', 'Nzd', 'Sgd']
	var limitsPromise any = this.PublicGetGetOrderMinimumVolumes(params)

	r := <-promiseAll([]any{baseCurrenciesPromise, quoteCurrenciesPromise, limitsPromise})
	if r.Err != nil {
		panic(r.Err)
	}
	var responses []any = ListTyped(r.Value)
	var limits any = this.SafeValue(responses, 2)
	//
	//     {
	//         "Xbt": 0.0001,
	//         "Eth": 0.001,
	//         "Ltc": 0.01,
	//         "Xrp": 1.0,
	//     }
	//
	var result []any = []any{}
	var baseCurrencyIds []any = this.ToArray(this.SafeValue(responses, 0))
	var quoteCurrencyIds []any = this.ToArray(this.SafeValue(responses, 1))
	for i := 0; i < len(baseCurrencyIds); i++ {
		var baseId *string = this.SafeString(baseCurrencyIds, i, "")
		var base *string = this.SafeCurrencyCode(baseId)
		var minAmount *float64 = this.SafeNumber(limits, baseId)
		for j := 0; j < len(quoteCurrencyIds); j++ {
			var quoteId *string = this.SafeString(quoteCurrencyIds, j, "")
			var quote *string = this.SafeCurrencyCode(quoteId)
			if (base == nil) || (quote == nil) {
				continue
			}
			var id string = *baseId + "/" + *quoteId
			result = append(result, map[string]any{
				"id":             id,
				"symbol":         *base + "/" + *quote,
				"base":           base,
				"quote":          quote,
				"settle":         nil,
				"baseId":         baseId,
				"quoteId":        quoteId,
				"settleId":       nil,
				"type":           "spot",
				"spot":           true,
				"margin":         false,
				"swap":           false,
				"future":         false,
				"option":         false,
				"active":         nil,
				"contract":       false,
				"linear":         nil,
				"inverse":        nil,
				"contractSize":   nil,
				"expiry":         nil,
				"expiryDatetime": nil,
				"strike":         nil,
				"optionType":     nil,
				"precision": map[string]any{
					"amount": nil,
					"price":  nil,
				},
				"limits": map[string]any{
					"leverage": map[string]any{
						"min": nil,
						"max": nil,
					},
					"amount": map[string]any{
						"min": minAmount,
						"max": nil,
					},
					"price": map[string]any{
						"min": nil,
						"max": nil,
					},
					"cost": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
				"created": nil,
				"info": map[string]any{
					"primaryCurrencyCode":   baseId,
					"secondaryCurrencyCode": quoteId,
				},
			})
		}
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}
func (this *Independentreserve) ParseBalanceList(response any) map[string]any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	var accounts []any = this.ToArray(response)
	for i := 0; i < len(accounts); i++ {
		var balance map[string]any = SafeMapTyped(accounts, i)
		var currencyId *string = this.SafeString(balance, "CurrencyCode")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(balance, "AvailableBalance")
		account["total"] = this.SafeString(balance, "TotalBalance")
		if code != nil {
			result[*code] = account
		}
	}
	return this.SafeBalance(result).(map[string]any)
}

/**
 * @method
 * @name independentreserve#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Independentreserve) FetchBalanceAsync(optionalArgs ...any) <-chan AsyncResult[Balances] {
	ch := make(chan AsyncResult[Balances], 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Independentreserve) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	listEp562 := <-this.PrivatePostGetAccounts(params)
	if listEp562.Err != nil {
		panic(listEp562.Err)
	}
	var response []any = listEp562.Value

	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.ParseBalanceList(response))}
	return nil
}

/**
 * @method
 * @name independentreserve#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Independentreserve) FetchOrderBookAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[OrderBook] {
	ch := make(chan AsyncResult[OrderBook], 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Independentreserve) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"primaryCurrencyCode":   market["baseId"],
		"secondaryCurrencyCode": market["quoteId"],
	}

	r1 := <-this.PublicGetGetOrderBook(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var timestamp *int64 = this.Parse8601(this.SafeString(response, "CreatedTimestampUtc"))

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(this.ParseOrderBook(response, market["symbol"], timestamp, "BuyOrders", "SellOrders", "Price", "Volume"))}
	return nil
}
func (this *Independentreserve) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	// {
	//     "DayHighestPrice":43489.49,
	//     "DayLowestPrice":41998.32,
	//     "DayAvgPrice":42743.9,
	//     "DayVolumeXbt":44.54515625000,
	//     "DayVolumeXbtInSecondaryCurrrency":0.12209818,
	//     "CurrentLowestOfferPrice":43619.64,
	//     "CurrentHighestBidPrice":43153.58,
	//     "LastPrice":43378.43,
	//     "PrimaryCurrencyCode":"Xbt",
	//     "SecondaryCurrencyCode":"Usd",
	//     "CreatedTimestampUtc":"2022-01-14T22:52:29.5029223Z"
	// }
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.Parse8601(this.SafeString(ticker, "CreatedTimestampUtc"))
	var baseId *string = this.SafeString(ticker, "PrimaryCurrencyCode")
	var quoteId *string = this.SafeString(ticker, "SecondaryCurrencyCode")
	var defaultMarketId any = nil
	if (baseId != nil) && (quoteId != nil) {
		defaultMarketId = *baseId + "/" + *quoteId
	}
	var marketResolved map[string]any = this.SafeMarket(defaultMarketId, market, "/")
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var last *string = this.SafeString(ticker, "LastPrice")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "DayHighestPrice"),
		"low":           this.SafeString(ticker, "DayLowestPrice"),
		"bid":           this.SafeString(ticker, "CurrentHighestBidPrice"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "CurrentLowestOfferPrice"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       this.SafeString(ticker, "DayAvgPrice"),
		"baseVolume":    this.SafeString(ticker, "DayVolumeXbtInSecondaryCurrrency"),
		"quoteVolume":   nil,
		"info":          ticker,
	}, marketResolved)
}

