func (this *Independentreserve) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// fetchOrder
	//
	//     {
	//         "OrderGuid": "c7347e4c-b865-4c94-8f74-d934d4b0b177",
	//         "CreatedTimestampUtc": "2014-09-23T12:39:34.3817763Z",
	//         "Type": "MarketBid",
	//         "VolumeOrdered": 5.0,
	//         "VolumeFilled": 5.0,
	//         "Price": null,
	//         "AvgPrice": 100.0,
	//         "ReservedAmount": 0.0,
	//         "Status": "Filled",
	//         "PrimaryCurrencyCode": "Xbt",
	//         "SecondaryCurrencyCode": "Usd"
	//     }
	//
	// fetchOpenOrders & fetchClosedOrders
	//
	//     {
	//         "OrderGuid": "b8f7ad89-e4e4-4dfe-9ea3-514d38b5edb3",
	//         "CreatedTimestampUtc": "2020-09-08T03:04:18.616367Z",
	//         "OrderType": "LimitOffer",
	//         "Volume": 0.0005,
	//         "Outstanding": 0.0005,
	//         "Price": 113885.83,
	//         "AvgPrice": 113885.83,
	//         "Value": 56.94,
	//         "Status": "Open",
	//         "PrimaryCurrencyCode": "Xbt",
	//         "SecondaryCurrencyCode": "Usd",
	//         "FeePercent": 0.005,
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "AvgPrice": 455.48,
	//        "CreatedTimestampUtc": "2022-08-05T06:42:11.3032208Z",
	//        "OrderGuid": "719c495c-a39e-4884-93ac-280b37245037",
	//        "Price": 485.76,
	//        "PrimaryCurrencyCode": "Xbt",
	//        "ReservedAmount": 0.358,
	//        "SecondaryCurrencyCode": "Usd",
	//        "Status": "Cancelled",
	//        "Type": "LimitOffer",
	//        "VolumeFilled": 0,
	//        "VolumeOrdered": 0.358
	//    }
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var symbol *string = nil
	var baseId *string = this.SafeString(order, "PrimaryCurrencyCode")
	var quoteId *string = this.SafeString(order, "SecondaryCurrencyCode")
	var base *string = nil
	var quote *string = nil
	if (baseId != nil) && (quoteId != nil) {
		base = this.SafeCurrencyCode(baseId)
		quote = this.SafeCurrencyCode(quoteId)
		if (base != nil) && (quote != nil) {
			symbol = SafeStringPtr(*base + "/" + *quote)
		}
	} else if market != nil {
		symbol = this.SafeString(market, "symbol")
		base = this.SafeString(market, "base")
		quote = this.SafeString(market, "quote")
	}
	var orderType *string = this.SafeString2(order, "Type", "OrderType")
	var side *string = nil
	if orderType != nil {
		if strings.Index(*orderType, "Bid") >= 0 {
			side = SafeStringPtr("buy")
		} else if strings.Index(*orderType, "Offer") >= 0 {
			side = SafeStringPtr("sell")
		}
		if strings.Index(*orderType, "Market") >= 0 {
			orderType = SafeStringPtr("market")
		} else if strings.Index(*orderType, "Limit") >= 0 {
			orderType = SafeStringPtr("limit")
		}
	}
	var timestamp *int64 = this.Parse8601(this.SafeString(order, "CreatedTimestampUtc"))
	var filled *string = this.SafeString(order, "VolumeFilled")
	var feeRate *string = this.SafeString(order, "FeePercent")
	var feeCost *string = nil
	if (feeRate != nil) && (filled != nil) {
		feeCost = Precise.StringMul(feeRate, filled)
	}
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 this.SafeString(order, "OrderGuid"),
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               orderType,
		"timeInForce":        this.ParseTimeInForce(this.SafeString(order, "TimeInForce")),
		"postOnly":           nil,
		"side":               side,
		"price":              this.SafeString(order, "Price"),
		"triggerPrice":       nil,
		"cost":               this.SafeString(order, "Value"),
		"average":            this.SafeString(order, "AvgPrice"),
		"amount":             this.SafeString2(order, "VolumeOrdered", "Volume"),
		"filled":             filled,
		"remaining":          this.SafeString(order, "Outstanding"),
		"status":             this.ParseOrderStatus(this.SafeString(order, "Status")),
		"fee": map[string]any{
			"rate":     feeRate,
			"cost":     feeCost,
			"currency": base,
		},
		"trades": nil,
	}, market)
}
func (this *Independentreserve) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"Open":                        "open",
		"PartiallyFilled":             "open",
		"Filled":                      "closed",
		"PartiallyFilledAndCancelled": "canceled",
		"Cancelled":                   "canceled",
		"PartiallyFilledAndExpired":   "canceled",
		"Expired":                     "canceled",
		"Failed":                      "canceled",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Independentreserve) ParseTimeInForce(timeInForce *string) *string {
	var timeInForces map[string]any = map[string]any{
		"Gtc": "GTC",
		"Moc": "PO",
		"Fok": "FOK",
		"Ioc": "IOC",
	}
	return this.SafeString(timeInForces, timeInForce, timeInForce)
}

