/**
 * @method
 * @name independentreserve#withdraw
 * @description make a withdrawal
 * @see https://www.independentreserve.com/features/api#WithdrawDigitalCurrency
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 *
 * EXCHANGE SPECIFIC PARAMETERS
 * @param {object} [params.comment] withdrawal comment, should not exceed 500 characters
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Independentreserve) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Independentreserve) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = nil
	tagWithdrawTag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	this.CheckAddress(address, code, tagWithdrawTag)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"primaryCurrencyCode": currency["id"],
		"withdrawalAddress":   address,
		"amount":              this.CurrencyToPrecision(code, amount),
	}
	if tagWithdrawTag != nil {
		request["destinationTag"] = *tagWithdrawTag
	}
	networkCode, paramsNetworkCode := this.HandleNetworkCodeAndParams(paramsWithdrawTag)
	if networkCode != nil {
		panic(BadRequest(this.Id + " withdraw () does not accept params[\"networkCode\"]"))
	}

	r1 := <-this.PrivatePostWithdrawDigitalCurrency(this.Extend(request, paramsNetworkCode))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//    {
	//        "TransactionGuid": "dc932e19-562b-4c50-821e-a73fd048b93b",
	//        "PrimaryCurrencyCode": "Bch",
	//        "CreatedTimestampUtc": "2020-04-01T05:26:30.5093622+00:00",
	//        "Amount": {
	//            "Total": 0.1231,
	//            "Fee": 0.0001
	//        },
	//        "Destination": {
	//            "Address": "bc1qhpqxkjpvgkckw530yfmxyr53c94q8f4273a7ez",
	//            "Tag": null
	//        },
	//        "Status": "Pending",
	//        "Transaction": null
	//    }
	//
	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}
func (this *Independentreserve) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	//    {
	//        "TransactionGuid": "dc932e19-562b-4c50-821e-a73fd048b93b",
	//        "PrimaryCurrencyCode": "Bch",
	//        "CreatedTimestampUtc": "2020-04-01T05:26:30.5093622+00:00",
	//        "Amount": {
	//            "Total": 0.1231,
	//            "Fee": 0.0001
	//        },
	//        "Destination": {
	//            "Address": "bc1qhpqxkjpvgkckw530yfmxyr53c94q8f4273a7ez",
	//            "Tag": null
	//        },
	//        "Status": "Pending",
	//        "Transaction": null
	//    }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var amount map[string]any = SafeMapTyped(transaction, "Amount")
	var destination map[string]any = SafeMapTyped(transaction, "Destination")
	var currencyId *string = this.SafeString(transaction, "PrimaryCurrencyCode")
	var datetime *string = this.SafeString(transaction, "CreatedTimestampUtc")
	var address *string = this.SafeString(destination, "Address")
	var tag *string = this.SafeString(destination, "Tag")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "TransactionGuid"),
		"txid":        nil,
		"type":        "withdraw",
		"currency":    code,
		"network":     nil,
		"amount":      this.SafeNumber(amount, "Total"),
		"status":      this.SafeString(transaction, "Status"),
		"timestamp":   this.Parse8601(datetime),
		"datetime":    datetime,
		"address":     address,
		"addressFrom": nil,
		"addressTo":   address,
		"tag":         tag,
		"tagFrom":     nil,
		"tagTo":       tag,
		"updated":     nil,
		"comment":     nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.SafeNumber(amount, "Fee"),
			"rate":     nil,
		},
		"internal": false,
	})
}
func (this *Independentreserve) Nonce() int64 {
	// the venue accepts any strictly-increasing integer, so use milliseconds: with the second-resolution base nonce a burst of N calls would leave incrementingNonce N seconds ahead of the clock
	return this.Milliseconds()
}
func (this *Independentreserve) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var apiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + "/" + path
	if apiName == "public" {
		if paramsMap, _ := params.(map[string]any); len(paramsMap) > 0 {
			url += "?" + this.Urlencode(params)
		}
	} else {
		this.CheckRequiredCredentials()
		// independentreserve requires an increasing nonce
		var rawNonce int64 = this.IncrementingNonce()
		var nonce int64 = this.ParseToInt(rawNonce)
		var auth []string = []string{url, "apiKey=" + this.ApiKey, "nonce=" + strconv.FormatInt(nonce, 10)}
		var paramsDict map[string]any = this.Extend(map[string]any{}, params)
		var keys []string = nil
		if paramsDict != nil {
			keys = make([]string, 0, len(paramsDict))
			for objectKey := range paramsDict {
				keys = append(keys, objectKey)
			}
		}
		for i := 0; i < len(keys); i++ {
			var key string = keys[i]
			var value string = *this.SafeString(paramsDict, key, "")
			auth = append(auth, key+"="+value)
		}
		var message string = strings.Join(auth, ",")
		var signature string = this.Hmac(this.Encode(message), this.Encode(this.Secret), sha256)
		var query map[string]any = map[string]any{}
		query["apiKey"] = this.ApiKey
		query["nonce"] = nonce
		query["signature"] = strings.ToUpper(signature)
		for i := 0; i < len(keys); i++ {
			var key string = keys[i]
			query[key] = paramsDict[key]
		}
		var signedBody string = this.Json(query)
		var signedHeaders map[string]any = map[string]any{
			"Content-Type": "application/json",
		}
		return map[string]any{
			"url":     url,
			"method":  method,
			"body":    signedBody,
			"headers": signedHeaders,
		}
	}
	var headers map[string]any = map[string]any{}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    nil,
		"headers": headers,
	}
}

func NewIndependentreserve(userConfig map[string]any) *Independentreserve {
	p := newIndependentreserve()
	p.Init(userConfig)
	return p
}

func (this *Independentreserve) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

